import json

log_path = r"C:\Users\divya\.gemini\antigravity\brain\46b300ac-7d96-4898-b657-324947eaf76e\.system_generated\logs\transcript_full.jsonl"

with open(log_path, "r", encoding="utf-8") as f:
    records = [json.loads(line) for line in f if line.strip()]

turns = []
current_turn = {"user": None, "assistant": [], "tools": [], "timestamp": None}

for r in records:
    t = r.get("type")
    if t == "USER_INPUT":
        if current_turn["user"] is not None:
            turns.append(current_turn)
            current_turn = {"user": None, "assistant": [], "tools": [], "timestamp": None}
        current_turn["user"] = r
        current_turn["timestamp"] = r.get("created_at")
    elif t == "PLANNER_RESPONSE":
        if r.get("content"):
            current_turn["assistant"].append(r.get("content"))
        if r.get("tool_calls"):
            for tc in r.get("tool_calls"):
                name = tc.get("name")
                summary = tc.get("args", {}).get("toolSummary", "")
                current_turn["tools"].append(f"{name}: {summary}" if summary else name)

if current_turn["user"] is not None:
    turns.append(current_turn)

print(f"Total structured turns: {len(turns)}")
for i, turn in enumerate(turns):
    user_txt = turn["user"].get("content", "").strip()
    # clean user text preview
    user_preview = user_txt.replace("<USER_REQUEST>", "").replace("</USER_REQUEST>", "").strip()[:60]
    media_count = len(turn["user"].get("media", []))
    asst_count = len(turn["assistant"])
    tools_count = len(turn["tools"])
    print(f"Turn {i+1:2d} | Media: {media_count} | Asst: {asst_count} | Tools: {tools_count:2d} | Prompt: {user_preview}")
